module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output [31:0] r,
    output zero, carry, negative, overflow, flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [32:0] res;
    reg carry_temp;
    reg overflow_temp;
    wire signed [31:0] a_signed = $signed(a);
    wire signed [31:0] b_signed = $signed(b);
    assign r = res[31:0];
    assign zero = (res[31:0] == 0);
    assign negative = res[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? ((aluc == SLT) ? ($signed(a) < $signed(b)) : (a < b)) : 1'b0;

    always @(*) begin
        case(aluc)
            ADD: begin
                res = a + b;
                carry_temp = res[32];
                overflow_temp = (~a[31] & ~b[31] & res[31]) | (a[31] & b[31] & ~res[31]);
            end
            ADDU: begin
                res = a + b;
                carry_temp = res[32];
                overflow_temp = 0;
            end
            SUB: begin
                res = a - b;
                carry_temp = res[32];
                overflow_temp = (a[31] & ~b[31] & ~res[31]) | (~a[31] & b[31] & res[31]);
            end
            SUBU: begin
                res = a - b;
                carry_temp = res[32];
                overflow_temp = 0;
            end
            AND: begin
                res = a & b;
                carry_temp = 0;
                overflow_temp = 0;
            end
            OR: begin
                res = a | b;
                carry_temp = 0;
                overflow_temp = 0;
            end
            XOR: begin
                res = a ^ b;
                carry_temp = 0;
                overflow_temp = 0;
            end
            NOR: begin
                res = ~(a | b);
                carry_temp = 0;
                overflow_temp = 0;
            end
            SLT: begin
                res = a_signed < b_signed ? 1 : 0;
                carry_temp = 0;
                overflow_temp = 0;
            end
            SLTU: begin
                res = a < b ? 1 : 0;
                carry_temp = 0;
                overflow_temp = 0;
            end
            SLL: begin
                res = b << a;
                carry_temp = 0;
                overflow_temp = 0;
            end
            SRL: begin
                res = b >> a;
                carry_temp = 0;
                overflow_temp = 0;
            end
            SRA: begin
                res = b_signed >>> a;
                carry_temp = 0;
                overflow_temp = 0;
            end
            SLLV: begin
                res = b << a[4:0];
                carry_temp = 0;
                overflow_temp = 0;
            end
            SRLV: begin
                res = b >> a[4:0];
                carry_temp = 0;
                overflow_temp = 0;
            end
            SRAV: begin
                res = b_signed >>> a[4:0];
                carry_temp = 0;
                overflow_temp = 0;
            end
            LUI: begin
                res = {a[15:0], 16'b0};
                carry_temp = 0;
                overflow_temp = 0;
            end
            default: begin
                res = 33'b0;
                carry_temp = 0;
                overflow_temp = 0;
            end
        endcase
    end

    assign carry = carry_temp;
    assign overflow = overflow_temp;
endmodule
